const raw = $input.item.json.message?.content ?? $input.item.json.choices?.[0]?.message?.content ?? '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch {
  parsed = { aiAnalysis: raw, keyFactors: [], confidenceScore: 60, edgeScore: '3.00' };
}
return [{
  json: {
    pick_id: $('ChalkPicks Pick Event').item.json.pick_id,
    aiAnalysis: parsed.aiAnalysis ?? '',
    keyFactors: Array.isArray(parsed.keyFactors) ? parsed.keyFactors : [],
    confidenceScore: Math.min(100, Math.max(1, parseInt(parsed.confidenceScore) || 60)),
    edgeScore: String(parseFloat(parsed.edgeScore) || 3.00),
  }
}];

